import React from 'react';
import './Register.css';
import heartImg from '../../assets/heart.png'; 
import logo from '../../assets/Logo.png';
import { FaUser, FaEnvelope, FaLock, FaIdCard } from 'react-icons/fa'; 
import { Link } from "react-router-dom";

const Register = () => {
  return (
    <div className="container-fluid register-container p-0">
      <div className="row min-vh-100">

        {/* Left Side */}
        <div
          className="col-lg-6 left-side d-flex flex-column justify-content-center align-items-center"
          style={{
            backgroundImage: `url(${heartImg})`,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
            position: 'relative',
          }}
        >
          <div
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              background: 'rgba(0,0,0,0.25)',
            }}
          ></div>
          <div className="logo-title-wrapper text-center" style={{ zIndex: 2 }}>
            <img src={logo} alt="logo" className="logo mb-3" />
            <h1 className="text-white">Heart Diseases</h1>
          </div>
        </div>

        {/* Right Side */}
        <div className="col-lg-6 right-side d-flex justify-content-center align-items-center">
          <div className="register-content p-4 rounded" style={{ width: '80%', maxWidth: '400px', background: 'rgba(245, 248, 255, 0.95)', boxShadow: '0 8px 20px rgba(0,0,0,0.1)' }}>
            
            <h2 className="text-center mb-4">Register Page</h2>

            {/* Email */}
            <div className="input-group mb-3 position-relative">
              <input type="email" className="form-control ps-4" placeholder="Email" />
              <FaEnvelope className="input-icon" />
            </div>

            {/* National ID */}
            <div className="input-group mb-3 position-relative">
              <input type="text" className="form-control ps-4" placeholder="National ID" />
              <FaIdCard className="input-icon" />
            </div>

            {/* Username */}
            <div className="input-group mb-3 position-relative">
              <input type="text" className="form-control ps-4" placeholder="Username" />
              <FaUser className="input-icon" />
            </div>

            {/* Password */}
            <div className="input-group mb-4 position-relative">
              <input type="password" className="form-control ps-4" placeholder="Password" />
              <FaLock className="input-icon" />
            </div>

            {/* Create Account Button */}
            <button className="btn w-100 btn-gradient mb-3">
              Create Account
            </button>

            {/* Login Link */}
            <div className="login-link text-center">
              Already have an account?{" "}
              <Link to="/login" className="text-primary text-decoration-none">
                Log In
              </Link>
            </div>

          </div>
        </div>

      </div>
    </div>
  );
};

export default Register;
